INSERT INTO message_translations (id, message_id, edit_id, translated_text, detected_language, confidence, translated_at, similarity_hash, chat_id) VALUES (47, 4575, NULL, 'Are you still using old paper cards that people often lose? In today’s digital era, is your business card also digital? We have brought for you a “Smart Digital Visiting Card.” Why not create a card that always stays on the customer’s phone and, with one click, delivers all your details to them?
